// CoordinatorAgent — STORY-011: Hold Summaries for Admin Review.
//
// Gherkin this satisfies (BC ticket 10068130468):
//   Given summaries have been generated by the SummaryGenerationAgent
//   When the CoordinatorAgent receives the summaries
//   Then summaries are held in a pending state for admin review,
//        with a notification sent to the admin within 15 minutes.
//
// Repository and notifier are injected (not imported directly) so this
// module is testable without a live Postgres connection — see
// app/tests/coordinatorAgent.test.js, which passes the in-memory doubles.
// In production, app/server.js wires in the real pg-backed repository
// and notifier instead.

const AUDIT_ACTION_SUMMARY_HELD = 'SUMMARY_HELD_FOR_REVIEW';
const AUDIT_ACTION_NOTIFICATION_SENT = 'ADMIN_NOTIFICATION_SENT';

function createCoordinatorAgent({ repository, notifier, auditLog, clock = () => new Date() }) {
    if (!repository) throw new Error('CoordinatorAgent requires a repository');
    if (!notifier) throw new Error('CoordinatorAgent requires a notifier');

    // Receives a summary object produced by SummaryGenerationAgent
    // ({ content, createdBy }) and holds it for admin review.
    async function receiveSummary({ content, createdBy = 'SummaryGenerationAgent' }) {
        if (!content || typeof content !== 'string' || content.trim() === '') {
            throw new Error('receiveSummary requires non-empty content');
        }

        const summary = await repository.create({ content, createdBy });

        if (auditLog) {
            await auditLog.record({
                action: AUDIT_ACTION_SUMMARY_HELD,
                details: { summaryId: summary.summary_id, createdBy },
            });
        }

        const notification = await notifier.notify({
            summaryId: summary.summary_id,
            message: `New summary pending review (from ${createdBy}).`,
        });

        if (auditLog) {
            await auditLog.record({
                action: AUDIT_ACTION_NOTIFICATION_SENT,
                details: { summaryId: summary.summary_id, notificationId: notification.notification_id },
            });
        }

        const notificationLatencyMs = new Date(notification.created_at) - new Date(summary.created_at);

        return { summary, notification, notificationLatencyMs };
    }

    async function listPendingForReview() {
        return repository.listPending();
    }

    async function recordAdminDecision(summaryId, decision, approvedBy) {
        if (decision !== 'approved' && decision !== 'rejected') {
            throw new Error(`recordAdminDecision: invalid decision "${decision}"`);
        }
        const updated = await repository.setStatus(summaryId, decision, approvedBy);
        if (!updated) {
            throw new Error(`recordAdminDecision: no summary found with id ${summaryId}`);
        }
        if (auditLog) {
            await auditLog.record({
                action: decision === 'approved' ? 'SUMMARY_APPROVED' : 'SUMMARY_REJECTED',
                details: { summaryId, approvedBy },
            });
        }
        return updated;
    }

    return { receiveSummary, listPendingForReview, recordAdminDecision };
}

module.exports = { createCoordinatorAgent, AUDIT_ACTION_SUMMARY_HELD, AUDIT_ACTION_NOTIFICATION_SENT };
